GtkWidget *insight_ai_embed(GtkWidget *container,const gchar *label,const gchar *context,GtkWidget *owner,InsightAiInsert cb,gpointer data) { return assistant_create(label,context,owner,cb,data,container); }
gboolean insight_ai_context_update(GtkWidget *controller,const gchar *context) { Assistant *a=g_object_get_data(G_OBJECT(controller),STATE);if(!a || a->closed || a->busy || !context || strlen(context)>65536 || !g_utf8_validate(context,-1,NULL)) return FALSE;set_text(a->context,context);return TRUE; }
gchar *insight_ai_suggested_command(GtkWidget *controller) { Assistant *a=g_object_get_data(G_OBJECT(controller),STATE);return a && !a->closed && !a->busy && a->response && insight_ai_command_valid(a->response->command) ? g_strdup(a->response->command):NULL; }
void insight_ai_lookup_for(const gchar *scope,const gchar *label,const gchar *context,const gchar *question) { GtkWidget *window=insight_ai_terminal_open(scope,label,context,NULL,NULL,NULL);Assistant *a=g_object_get_data(G_OBJECT(window),STATE);insight_ai_console_set_prompt(a->question,question ? question:""); }
void insight_ai_help_question(const gchar *context,const gchar *question) {GtkWidget *window=insight_ai_terminal_open("program-help","Program help — review captured text",context,NULL,NULL,NULL);Assistant *a=g_object_get_data(G_OBJECT(window),STATE);insight_ai_console_set_prompt(a->question,question);send_question(NULL,a);}
static void answer_in_help(GtkWidget *widget,gpointer data) {(void)widget;Assistant *a=data;if(a->response) {gint n=gtk_combo_box_get_active(GTK_COMBO_BOX(a->turn_list));AiTurn *turn=n>=0 && (guint)n<a->turns->len ? g_ptr_array_index(a->turns,n):NULL;insight_help_answer(turn ? turn->question:NULL,a->response->explanation);}}
void insight_ai_lookup(const gchar *label,const gchar *context,const gchar *question) { insight_ai_lookup_for("source-help",label,context,question); }
static void lookup_selection(GtkWidget *widget,gpointer data) {
 (void)widget;(void)data;GeanyDocument *doc=document_get_current();if(!DOC_VALID(doc)) return;ScintillaObject *sci=doc->editor->sci;
 if(SEND(sci,SCI_GETSELECTIONS,0,0)!=1 || sci_get_selection_mode(sci)!=SC_SEL_STREAM || SEND(sci,SCI_GETSELECTIONNCARETVIRTUALSPACE,0,0) || SEND(sci,SCI_GETSELECTIONNANCHORVIRTUALSPACE,0,0)) { ui_set_statusbar(FALSE,"%s",insight_tr("Select ordinary source text for AI lookup"));return; }
 gint a=SEND(sci,SCI_GETSELECTIONSTART,0,0),b=SEND(sci,SCI_GETSELECTIONEND,0,0);if(a==b) { a=SEND(sci,SCI_WORDSTARTPOSITION,a,TRUE);b=SEND(sci,SCI_WORDENDPOSITION,b,TRUE); }if(b<=a || b-a>65536) { ui_set_statusbar(FALSE,"%s",insight_tr("AI lookup selection is limited to 64 KiB"));return; }gchar *text=sci_get_contents_range(sci,a,b);if(g_utf8_validate(text,b-a,NULL) && !memchr(text,0,b-a)) insight_ai_lookup("Source selection — AI lookup",text,"Explain this selection, identify relevant functions or algorithms, and suggest useful documentation. Distinguish facts from uncertainty.");g_free(text);
}
static void open_manual(GtkWidget *widget,gpointer data) { (void)widget;(void)data;insight_ai_open("Console output — paste or edit context before sending","",NULL,NULL,NULL); }
void insight_ai_init(void) { if(initialized) return;initialized=TRUE;GtkWidget *menu=ui_lookup_widget(main_widgets.window,"tools1_menu");if(!menu) menu=gtk_menu_item_get_submenu(GTK_MENU_ITEM(ui_lookup_widget(main_widgets.window,"tools1")));GtkWidget *item=gtk_menu_item_new_with_label(insight_tr("Console AI Assistant…"));gtk_widget_set_name(item,"insight-ai-menu");gtk_menu_shell_append(GTK_MENU_SHELL(menu),item);g_signal_connect(item,"activate",G_CALLBACK(open_manual),NULL);gtk_widget_show(item);GtkWidget *settings=gtk_menu_item_new_with_label(insight_tr("AI Connections…"));gtk_widget_set_name(settings,"insight-ai-connections-menu");gtk_menu_shell_append(GTK_MENU_SHELL(menu),settings);g_signal_connect(settings,"activate",G_CALLBACK(insight_ai_profiles_show),NULL);gtk_widget_show(settings);GtkWidget *menus[]={ui_lookup_widget(main_widgets.window,"search1_menu"),main_widgets.editor_menu};for(guint i=0;i<2;i++) { GtkWidget *lookup=gtk_menu_item_new_with_label(insight_tr("Look up selection with AI…"));gtk_widget_set_name(lookup,i ? "insight-ai-lookup-popup":"insight-ai-lookup-menu");g_signal_connect(lookup,"activate",G_CALLBACK(lookup_selection),NULL);gtk_menu_shell_append(GTK_MENU_SHELL(menus[i]),lookup);gtk_widget_show(lookup); } }
